# ! [doc = " For each definition, we track the following data. A definition"] # ! [doc = " here is defined somewhat circularly as \"something with a `DefId`\","] # ! [doc = " but it generally corresponds to things like structs, enums, etc."] # ! [doc = " There are also some rather random cases (like const initializer"] # ! [doc = " expressions) that are mostly just leftovers."] use split_decls_genesis :: ourprelude :: * ; use std :: fmt :: { self , Write } ; use std :: hash :: Hash ; use rustc_data_structures :: stable_hasher :: StableHasher ; use rustc_data_structures :: unord :: UnordMap ; use rustc_hashes :: Hash64 ; use rustc_index :: IndexVec ; use rustc_macros :: { Decodable , Encodable } ; use rustc_span :: { Symbol , kw , sym } ; use tracing :: { debug , instrument } ; pub use crate :: def_id :: DefPathHash ; use crate :: def_id :: { CRATE_DEF_INDEX , CrateNum , DefIndex , LOCAL_CRATE , LocalDefId , StableCrateId } ; use crate :: def_path_hash_map :: DefPathHashMap ; #[doc = " The `DefPathTable` maps `DefIndex`es to `DefKey`s and vice versa."] #[doc = " Internally the `DefPathTable` holds a tree of `DefKey`s, where each `DefKey`"] #[doc = " stores the `DefIndex` of its parent."] #[doc = " There is one `DefPathTable` for each crate."] #[derive (Debug)] pub struct DefPathTable { stable_crate_id : StableCrateId , index_to_key : IndexVec < DefIndex , DefKey > , def_path_hashes : IndexVec < DefIndex , Hash64 > , def_path_hash_to_index : DefPathHashMap , } impl DefPathTable { fn new (stable_crate_id : StableCrateId) -> DefPathTable { DefPathTable { stable_crate_id , index_to_key : Default :: default () , def_path_hashes : Default :: default () , def_path_hash_to_index : Default :: default () , } } fn allocate (& mut self , key : DefKey , def_path_hash : DefPathHash) -> DefIndex { debug_assert_eq ! (self . stable_crate_id , def_path_hash . stable_crate_id ()) ; let local_hash = def_path_hash . local_hash () ; let index = self . index_to_key . push (key) ; debug ! ("DefPathTable::insert() - {key:?} <-> {index:?}") ; self . def_path_hashes . push (local_hash) ; debug_assert ! (self . def_path_hashes . len () == self . index_to_key . len ()) ; if let Some (existing) = self . def_path_hash_to_index . insert (& local_hash , & index) { let def_path1 = DefPath :: make (LOCAL_CRATE , existing , | idx | self . def_key (idx)) ; let def_path2 = DefPath :: make (LOCAL_CRATE , index , | idx | self . def_key (idx)) ; panic ! ("found DefPathHash collision between {def_path1:#?} and {def_path2:#?}. \
                    Compilation cannot continue.") ; } index } #[inline (always)] pub fn def_key (& self , index : DefIndex) -> DefKey { self . index_to_key [index] } #[instrument (level = "trace" , skip (self) , ret)] #[inline (always)] pub fn def_path_hash (& self , index : DefIndex) -> DefPathHash { let hash = self . def_path_hashes [index] ; DefPathHash :: new (self . stable_crate_id , hash) } pub fn enumerated_keys_and_path_hashes (& self ,) -> impl Iterator < Item = (DefIndex , & DefKey , DefPathHash) > + ExactSizeIterator { self . index_to_key . iter_enumerated () . map (move | (index , key) | (index , key , self . def_path_hash (index))) } } #[derive (Debug)] pub struct DisambiguatorState { next : UnordMap < (LocalDefId , DefPathData) , u32 > , } impl DisambiguatorState { pub fn new () -> Self { Self { next : Default :: default () } } #[doc = " Creates a `DisambiguatorState` where the next allocated `(LocalDefId, DefPathData)` pair"] #[doc = " will have `index` as the disambiguator."] pub fn with (def_id : LocalDefId , data : DefPathData , index : u32) -> Self { let mut this = Self :: new () ; this . next . insert ((def_id , data) , index) ; this } } #[doc = " The definition table containing node definitions."] #[doc = " It holds the `DefPathTable` for `LocalDefId`s/`DefPath`s."] #[doc = " It also stores mappings to convert `LocalDefId`s to/from `HirId`s."] #[derive (Debug)] pub struct Definitions { table : DefPathTable , } #[doc = " A unique identifier that we can use to lookup a definition"] #[doc = " precisely. It combines the index of the definition's parent (if"] #[doc = " any) with a `DisambiguatedDefPathData`."] #[derive (Copy , Clone , PartialEq , Debug , Encodable , Decodable)] pub struct DefKey { #[doc = " The parent path."] pub parent : Option < DefIndex > , #[doc = " The identifier of this node."] pub disambiguated_data : DisambiguatedDefPathData , } impl DefKey { pub (crate) fn compute_stable_hash (& self , parent : DefPathHash) -> DefPathHash { let mut hasher = StableHasher :: new () ; parent . local_hash () . hash (& mut hasher) ; let DisambiguatedDefPathData { ref data , disambiguator } = self . disambiguated_data ; std :: mem :: discriminant (data) . hash (& mut hasher) ; if let Some (name) = data . hashed_symbol () { name . as_str () . hash (& mut hasher) ; } disambiguator . hash (& mut hasher) ; let local_hash = hasher . finish () ; DefPathHash :: new (parent . stable_crate_id () , local_hash) } #[inline] pub fn get_opt_name (& self) -> Option < Symbol > { self . disambiguated_data . data . get_opt_name () } } #[doc = " A pair of `DefPathData` and an integer disambiguator. The integer is"] #[doc = " normally `0`, but in the event that there are multiple defs with the"] #[doc = " same `parent` and `data`, we use this field to disambiguate"] #[doc = " between them. This introduces some artificial ordering dependency"] #[doc = " but means that if you have, e.g., two impls for the same type in"] #[doc = " the same module, they do get distinct `DefId`s."] #[derive (Copy , Clone , PartialEq , Debug , Encodable , Decodable)] pub struct DisambiguatedDefPathData { pub data : DefPathData , pub disambiguator : u32 , } impl DisambiguatedDefPathData { pub fn as_sym (& self , verbose : bool) -> Symbol { match self . data . name () { DefPathDataName :: Named (name) => { if verbose && self . disambiguator != 0 { Symbol :: intern (& format ! ("{}#{}" , name , self . disambiguator)) } else { name } } DefPathDataName :: Anon { namespace } => { if let DefPathData :: AnonAssocTy (method) = self . data { Symbol :: intern (& format ! ("{}::{{{}#{}}}" , method , namespace , self . disambiguator)) } else { Symbol :: intern (& format ! ("{{{}#{}}}" , namespace , self . disambiguator)) } } } } } #[derive (Clone , Debug , Encodable , Decodable)] pub struct DefPath { #[doc = " The path leading from the crate root to the item."] pub data : Vec < DisambiguatedDefPathData > , #[doc = " The crate root this path is relative to."] pub krate : CrateNum , } impl DefPath { pub fn make < FN > (krate : CrateNum , start_index : DefIndex , mut get_key : FN) -> DefPath where FN : FnMut (DefIndex) -> DefKey , { let mut data = vec ! [] ; let mut index = Some (start_index) ; loop { debug ! ("DefPath::make: krate={:?} index={:?}" , krate , index) ; let p = index . unwrap () ; let key = get_key (p) ; debug ! ("DefPath::make: key={:?}" , key) ; match key . disambiguated_data . data { DefPathData :: CrateRoot => { assert ! (key . parent . is_none ()) ; break ; } _ => { data . push (key . disambiguated_data) ; index = key . parent ; } } } data . reverse () ; DefPath { data , krate } } #[doc = " Returns a string representation of the `DefPath` without"] #[doc = " the crate-prefix. This method is useful if you don't have"] #[doc = " a `TyCtxt` available."] pub fn to_string_no_crate_verbose (& self) -> String { let mut s = String :: with_capacity (self . data . len () * 16) ; for component in & self . data { write ! (s , "::{}" , component . as_sym (true)) . unwrap () ; } s } #[doc = " Returns a filename-friendly string of the `DefPath`, without"] #[doc = " the crate-prefix. This method is useful if you don't have"] #[doc = " a `TyCtxt` available."] pub fn to_filename_friendly_no_crate (& self) -> String { let mut s = String :: with_capacity (self . data . len () * 16) ; let mut opt_delimiter = None ; for component in & self . data { s . extend (opt_delimiter) ; opt_delimiter = Some ('-') ; write ! (s , "{}" , component . as_sym (true)) . unwrap () ; } s } } #[doc = " New variants should only be added in synchronization with `enum DefKind`."] #[derive (Copy , Clone , Debug , PartialEq , Eq , Hash , Encodable , Decodable)] pub enum DefPathData { #[doc = " The crate root (marker)."] CrateRoot , #[doc = " An impl."] Impl , #[doc = " An `extern` block."] ForeignMod , #[doc = " A `use` item."] Use , #[doc = " A global asm item."] GlobalAsm , #[doc = " Something in the type namespace."] TypeNs (Symbol) , #[doc = " Something in the value namespace."] ValueNs (Symbol) , #[doc = " Something in the macro namespace."] MacroNs (Symbol) , #[doc = " Something in the lifetime namespace."] LifetimeNs (Symbol) , #[doc = " A closure expression."] Closure , #[doc = " Implicit constructor for a unit or tuple-like struct or enum variant."] Ctor , #[doc = " A constant expression (see `{ast,hir}::AnonConst`)."] AnonConst , #[doc = " An existential `impl Trait` type node."] #[doc = " Argument position `impl Trait` have a `TypeNs` with their pretty-printed name."] OpaqueTy , #[doc = " Used for remapped captured lifetimes in an existential `impl Trait` type node."] OpaqueLifetime (Symbol) , #[doc = " An anonymous associated type from an RPITIT. The symbol refers to the name of the method"] #[doc = " that defined the type."] AnonAssocTy (Symbol) , #[doc = " A synthetic body for a coroutine's by-move body."] SyntheticCoroutineBody , #[doc = " Additional static data referred to by a static."] NestedStatic , } impl Definitions { pub fn def_path_table (& self) -> & DefPathTable { & self . table } #[doc = " Gets the number of definitions."] pub fn def_index_count (& self) -> usize { self . table . index_to_key . len () } #[inline] pub fn def_key (& self , id : LocalDefId) -> DefKey { self . table . def_key (id . local_def_index) } #[inline (always)] pub fn def_path_hash (& self , id : LocalDefId) -> DefPathHash { self . table . def_path_hash (id . local_def_index) } #[doc = " Returns the path from the crate root to `index`. The root"] #[doc = " nodes are not included in the path (i.e., this will be an"] #[doc = " empty vector for the crate root). For an inlined item, this"] #[doc = " will be the path of the item in the external crate (but the"] #[doc = " path will begin with the path to the external crate)."] pub fn def_path (& self , id : LocalDefId) -> DefPath { DefPath :: make (LOCAL_CRATE , id . local_def_index , | index | { self . def_key (LocalDefId { local_def_index : index }) }) } #[doc = " Adds a root definition (no parent) and a few other reserved definitions."] pub fn new (stable_crate_id : StableCrateId) -> Definitions { let key = DefKey { parent : None , disambiguated_data : DisambiguatedDefPathData { data : DefPathData :: CrateRoot , disambiguator : 0 , } , } ; let def_path_hash = DefPathHash :: new (stable_crate_id , Hash64 :: new (stable_crate_id . as_u64 ())) ; let mut table = DefPathTable :: new (stable_crate_id) ; let root = LocalDefId { local_def_index : table . allocate (key , def_path_hash) } ; assert_eq ! (root . local_def_index , CRATE_DEF_INDEX) ; Definitions { table } } #[doc = " Creates a definition with a parent definition."] #[doc = " If there are multiple definitions with the same DefPathData and the same parent, use"] #[doc = " `disambiguator` to differentiate them. Distinct `DisambiguatorState` instances are not"] #[doc = " guaranteed to generate unique disambiguators and should instead ensure that the `parent`"] #[doc = " and `data` pair is distinct from other instances."] pub fn create_def (& mut self , parent : LocalDefId , data : DefPathData , disambiguator : & mut DisambiguatorState ,) -> LocalDefId { debug ! ("create_def(parent={}, data={data:?})" , self . def_path (parent) . to_string_no_crate_verbose () ,) ; assert ! (data != DefPathData :: CrateRoot) ; let disambiguator = { let next_disamb = disambiguator . next . entry ((parent , data)) . or_insert (0) ; let disambiguator = * next_disamb ; * next_disamb = next_disamb . checked_add (1) . expect ("disambiguator overflow") ; disambiguator } ; let key = DefKey { parent : Some (parent . local_def_index) , disambiguated_data : DisambiguatedDefPathData { data , disambiguator } , } ; let parent_hash = self . table . def_path_hash (parent . local_def_index) ; let def_path_hash = key . compute_stable_hash (parent_hash) ; debug ! ("create_def: after disambiguation, key = {:?}" , key) ; LocalDefId { local_def_index : self . table . allocate (key , def_path_hash) } } #[inline (always)] #[doc = " Returns `None` if the `DefPathHash` does not correspond to a `LocalDefId`"] #[doc = " in the current compilation session. This can legitimately happen if the"] #[doc = " `DefPathHash` is from a `DefId` in an upstream crate or, during incr. comp.,"] #[doc = " if the `DefPathHash` is from a previous compilation session and"] #[doc = " the def-path does not exist anymore."] pub fn local_def_path_hash_to_def_id (& self , hash : DefPathHash) -> Option < LocalDefId > { debug_assert ! (hash . stable_crate_id () == self . table . stable_crate_id) ; self . table . def_path_hash_to_index . get (& hash . local_hash ()) . map (| local_def_index | LocalDefId { local_def_index }) } pub fn def_path_hash_to_def_index_map (& self) -> & DefPathHashMap { & self . table . def_path_hash_to_index } pub fn num_definitions (& self) -> usize { self . table . def_path_hashes . len () } } #[derive (Copy , Clone , PartialEq , Debug)] pub enum DefPathDataName { Named (Symbol) , Anon { namespace : Symbol } , } impl DefPathData { pub fn get_opt_name (& self) -> Option < Symbol > { use self :: DefPathData :: * ; match * self { TypeNs (name) | ValueNs (name) | MacroNs (name) | LifetimeNs (name) | OpaqueLifetime (name) => Some (name) , Impl | ForeignMod | CrateRoot | Use | GlobalAsm | Closure | Ctor | AnonConst | OpaqueTy | AnonAssocTy (..) | SyntheticCoroutineBody | NestedStatic => None , } } fn hashed_symbol (& self) -> Option < Symbol > { use self :: DefPathData :: * ; match * self { TypeNs (name) | ValueNs (name) | MacroNs (name) | LifetimeNs (name) | AnonAssocTy (name) | OpaqueLifetime (name) => Some (name) , Impl | ForeignMod | CrateRoot | Use | GlobalAsm | Closure | Ctor | AnonConst | OpaqueTy | SyntheticCoroutineBody | NestedStatic => None , } } pub fn name (& self) -> DefPathDataName { use self :: DefPathData :: * ; match * self { TypeNs (name) | ValueNs (name) | MacroNs (name) | LifetimeNs (name) | OpaqueLifetime (name) => DefPathDataName :: Named (name) , CrateRoot => DefPathDataName :: Anon { namespace : kw :: Crate } , Impl => DefPathDataName :: Anon { namespace : kw :: Impl } , ForeignMod => DefPathDataName :: Anon { namespace : kw :: Extern } , Use => DefPathDataName :: Anon { namespace : kw :: Use } , GlobalAsm => DefPathDataName :: Anon { namespace : sym :: global_asm } , Closure => DefPathDataName :: Anon { namespace : sym :: closure } , Ctor => DefPathDataName :: Anon { namespace : sym :: constructor } , AnonConst => DefPathDataName :: Anon { namespace : sym :: constant } , OpaqueTy => DefPathDataName :: Anon { namespace : sym :: opaque } , AnonAssocTy (..) => DefPathDataName :: Anon { namespace : sym :: anon_assoc } , SyntheticCoroutineBody => DefPathDataName :: Anon { namespace : sym :: synthetic } , NestedStatic => DefPathDataName :: Anon { namespace : sym :: nested } , } } } impl fmt :: Display for DefPathData { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { match self . name () { DefPathDataName :: Named (name) => f . write_str (name . as_str ()) , DefPathDataName :: Anon { namespace } => write ! (f , "{{{{{namespace}}}}}") , } } }